           // Client experience & skeleton loaders\n];\n\nforeach ($sedrazavi_essential_includes as $file_rel) {\n    $full_path = SEDRAZAVI_THEME_DIR . '/' . $file_rel;\n    if (file_exists($full_path)) {\n        require_once $full_path;\n    }\n}\n"
